INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 9.638, -470.0, 0.0, 10023, 2002, "カリザ", 6, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 3, "2024/09/15 15:00:00", 5, "2024/12/22 14:59:59", 133301);
