INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 0.0, -470.0, 0.0, 10032, 2002, "デュラン", 8, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 2, "2025/03/15 15:00:00", 1, "2025/06/23 14:59:59", 137001);
