INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 4.935, -470.0, 0.0, 10035, 2002, "サツキ", 9, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 1, "2025/06/16 15:00:00", 6, "2025/09/23 14:59:59", 135902);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 7.441, -470.0, 0.0, 10036, 2002, "ユキノ", 9, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 2, "2025/06/16 15:00:00", 5, "2025/09/23 14:59:59", 135802);
