INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 2.295, -470.0, 0.0, 10038, 2002, "クルル", 10, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2, "2025/09/16 15:00:00", 2, "2025/12/22 14:59:59", 130901);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 6.281, -470.0, 0.0, 10039, 2002, "クルル", 10, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 1, "2025/09/16 15:00:00", 6, "2025/12/22 14:59:59", 130901);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 5.549, -470.0, 0.0, 10040, 2002, "ヴォルガーノ", 10, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 2, "2025/09/16 15:00:00", 1, "2025/12/22 14:59:59", 137701);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 2.64, -470.0, 0.0, 10041, 2002, "ヴォルガーノ", 10, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 3, "2025/09/16 15:00:00", 6, "2025/12/22 14:59:59", 137701);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 7.642, -470.0, 0.0, 10042, 2002, "ライラエル", 11, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 7, "2025/12/15 15:00:00", 4, "2026/03/23 11:59:59", 132801);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 0.0, -470.0, 0.0, 10043, 2002, "ライラエル", 11, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 1, "2025/12/15 15:00:00", 1, "2026/03/23 11:59:59", 132802);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 0.0, -470.0, 0.0, 10044, 2002, "クローチェ", 11, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, "2025/12/15 15:00:00", 1, "2026/03/23 11:59:59", 134502);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 3.72, -470.0, 0.0, 10045, 2002, "クローチェ", 11, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 2, "2025/12/15 15:00:00", 1, "2026/03/23 11:59:59", 134501);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 4.991, -470.0, 0.0, 10046, 2002, "ネフィ＝ネラ", 12, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 2, "2026/03/16 12:00:00", 1, "2026/06/22 11:59:59", 138201);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 3.877, -470.0, 0.0, 10047, 2002, "ネフィ＝ネラ", 12, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 1, "2026/03/16 12:00:00", 4, "2026/06/22 11:59:59", 138201);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 1.71, -470.0, 0.0, 10048, 2002, "アラクネ", 12, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 4, "2026/03/16 12:00:00", 6, "2026/06/22 11:59:59", 136001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 5.32, -470.0, 0.0, 10049, 2002, "アラクネ", 12, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 5, "2026/03/16 12:00:00", 2, "2026/06/22 11:59:59", 136001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 3.727, -470.0, 0.0, 10050, 2002, "アネモネ", 13, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 9, "2026/06/15 12:00:00", 4, "2026/09/22 11:59:59", 135401);
